-- Location lists for address forms: Indian states, their districts and the
-- cities/towns in each district. Forms show these as cascading dropdowns
-- (State -> District -> City). When a value is missing the user picks
-- "Other" and types it; that raises a location request which platform staff
-- approve (the value is added to the list) or reject.
--
-- Seed data: states and districts from the india-location-kit npm package
-- (MIT), cities from the countries-states-cities database (ODbL) placed in
-- districts using India Post office locations (india-pincode, MIT). See
-- docs/locations.md.

-------------------------------------------------------------------------------
-- Tables
-------------------------------------------------------------------------------

create table public.location_states (
  id smallint generated always as identity primary key,
  code text unique check (code ~ '^[A-Z]{2,3}$'),
  name text not null check (char_length(trim(name)) between 2 and 80),
  is_union_territory boolean not null default false,
  created_at timestamptz not null default now()
);
create unique index location_states_name_key on public.location_states (lower(name));

create table public.location_districts (
  id int generated always as identity primary key,
  state_id smallint not null references public.location_states (id) on delete cascade,
  name text not null check (char_length(trim(name)) between 2 and 80),
  created_at timestamptz not null default now()
);
create unique index location_districts_name_key on public.location_districts (state_id, lower(name));

create table public.location_cities (
  id int generated always as identity primary key,
  district_id int not null references public.location_districts (id) on delete cascade,
  name text not null check (char_length(trim(name)) between 2 and 80),
  created_at timestamptz not null default now()
);
create unique index location_cities_name_key on public.location_cities (district_id, lower(name));

comment on table public.location_states is 'Indian states and union territories offered in address dropdowns.';
comment on table public.location_districts is 'Districts per state, offered after a state is picked.';
comment on table public.location_cities is 'Cities and towns per district, offered after a district is picked.';

create type public.location_kind as enum ('state', 'district', 'city');
create type public.location_request_status as enum ('pending', 'approved', 'rejected');

-- A value typed under "Other". The parents are names, not ids, because they
-- may be new too (a new district in a new state).
create table public.location_requests (
  id uuid primary key default gen_random_uuid(),
  kind public.location_kind not null,
  state_name text not null check (char_length(trim(state_name)) between 2 and 80),
  district_name text check (district_name is null or char_length(trim(district_name)) between 2 and 80),
  city_name text check (city_name is null or char_length(trim(city_name)) between 2 and 80),
  context text check (context is null or char_length(context) <= 200),
  status public.location_request_status not null default 'pending',
  requested_by uuid references public.profiles (id) on delete set null,
  decided_by uuid references public.profiles (id) on delete set null,
  decided_at timestamptz,
  decision_note text check (decision_note is null or char_length(decision_note) <= 500),
  created_at timestamptz not null default now(),
  check ((kind = 'state' and district_name is null and city_name is null)
      or (kind = 'district' and district_name is not null and city_name is null)
      or (kind = 'city' and district_name is not null and city_name is not null))
);
create unique index location_requests_pending_key on public.location_requests
  (kind, lower(state_name), lower(coalesce(district_name, '')), lower(coalesce(city_name, '')))
  where status = 'pending';
create index location_requests_status_idx on public.location_requests (status, created_at desc);

alter table public.location_states enable row level security;
alter table public.location_districts enable row level security;
alter table public.location_cities enable row level security;
alter table public.location_requests enable row level security;

-- Lists are public: the customer app may show them before sign-in.
create policy location_states_select on public.location_states for select to anon, authenticated using (true);
create policy location_districts_select on public.location_districts for select to anon, authenticated using (true);
create policy location_cities_select on public.location_cities for select to anon, authenticated using (true);
create policy location_requests_select on public.location_requests for select to authenticated
  using (requested_by = (select auth.uid()) or private.has_platform_permission('locations.manage'));

insert into public.platform_permissions (code, description) values
  ('locations.manage', 'Approve or reject new states, districts and cities requested from address forms')
on conflict do nothing;
insert into public.platform_role_permissions (role, permission) values ('admin', 'locations.manage')
on conflict do nothing;

-- Businesses get a district on the registered address, like stations.
alter table public.businesses add column if not exists registered_district text;

-------------------------------------------------------------------------------
-- Functions
-------------------------------------------------------------------------------

create or replace function private.clean_location_name(p_name text)
returns text
language sql
immutable
set search_path = ''
as $$
  select nullif(regexp_replace(trim(coalesce(p_name, '')), '\s+', ' ', 'g'), '');
$$;

-- Add a state/district/city to the lists (and any missing parent). Returns
-- the id of the deepest level added or found.
create or replace function private.ensure_location(p_state text, p_district text, p_city text)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_state smallint;
  v_district int;
  v_city int;
begin
  select id into v_state from public.location_states where lower(name) = lower(p_state);
  if v_state is null then
    insert into public.location_states (name) values (p_state) returning id into v_state;
  end if;
  if p_district is null then
    return v_state;
  end if;
  select id into v_district from public.location_districts where state_id = v_state and lower(name) = lower(p_district);
  if v_district is null then
    insert into public.location_districts (state_id, name) values (v_state, p_district) returning id into v_district;
  end if;
  if p_city is null then
    return v_district;
  end if;
  select id into v_city from public.location_cities where district_id = v_district and lower(name) = lower(p_city);
  if v_city is null then
    insert into public.location_cities (district_id, name) values (v_district, p_city) returning id into v_city;
  end if;
  return v_city;
end;
$$;

-- Raise a request for a value typed under "Other". If the value is already
-- in the list, or already requested, nothing new is created. Returns
-- {status: 'exists' | 'pending', request_id}.
create or replace function public.request_location(
  p_kind public.location_kind,
  p_state text,
  p_district text default null,
  p_city text default null,
  p_context text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_state text := private.clean_location_name(p_state);
  v_district text := case when p_kind in ('district', 'city') then private.clean_location_name(p_district) end;
  v_city text := case when p_kind = 'city' then private.clean_location_name(p_city) end;
  v_id uuid;
  v_label text;
begin
  if v_user is null then
    perform private.raise_error(401, 'not_authenticated');
  end if;
  if v_state is null or (p_kind in ('district', 'city') and v_district is null) or (p_kind = 'city' and v_city is null) then
    perform private.raise_error(422, 'location_name_required', 'Enter the name');
  end if;
  if char_length(coalesce(v_city, v_district, v_state)) not between 2 and 80 then
    perform private.raise_error(422, 'location_name_invalid', 'Names must be 2 to 80 characters');
  end if;
  if (select count(*) from public.location_requests
       where requested_by = v_user and created_at > now() - interval '1 day') >= 20 then
    perform private.raise_error(422, 'too_many_requests', 'Too many location requests today');
  end if;

  if exists (
    select 1 from public.location_states s
      left join public.location_districts d on d.state_id = s.id and lower(d.name) = lower(v_district)
      left join public.location_cities c on c.district_id = d.id and lower(c.name) = lower(v_city)
     where lower(s.name) = lower(v_state)
       and (p_kind = 'state' or d.id is not null)
       and (p_kind <> 'city' or c.id is not null)) then
    return jsonb_build_object('status', 'exists');
  end if;

  select id into v_id from public.location_requests
   where status = 'pending' and kind = p_kind and lower(state_name) = lower(v_state)
     and lower(coalesce(district_name, '')) = lower(coalesce(v_district, ''))
     and lower(coalesce(city_name, '')) = lower(coalesce(v_city, ''));
  if v_id is not null then
    return jsonb_build_object('status', 'pending', 'request_id', v_id);
  end if;

  insert into public.location_requests (kind, state_name, district_name, city_name, context, requested_by)
  values (p_kind, v_state, v_district, v_city, left(nullif(trim(p_context), ''), 200), v_user)
  returning id into v_id;

  v_label := concat_ws(', ', v_city, v_district, v_state);
  perform private.notify_platform_staff('locations.manage', 'system', 'location.requested',
    'New ' || p_kind::text || ' requested', 'Please review "' || v_label || '" for the address lists.',
    jsonb_build_object('location_request_id', v_id), 'location.requested:' || v_id);
  return jsonb_build_object('status', 'pending', 'request_id', v_id);
end;
$$;

-- Approve (adds the value, and any missing parent, to the lists) or reject.
-- The admin may correct the spelling while approving.
create or replace function public.decide_location_request(
  p_request_id uuid,
  p_approve boolean,
  p_note text default null,
  p_state text default null,
  p_district text default null,
  p_city text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.location_requests;
  v_state text;
  v_district text;
  v_city text;
begin
  perform private.require_platform_permission('locations.manage');
  select * into r from public.location_requests where id = p_request_id for update;
  if not found then
    perform private.raise_error(404, 'location_request_not_found');
  end if;
  if r.status <> 'pending' then
    perform private.raise_error(409, 'location_request_decided', 'This request was already decided');
  end if;
  if not p_approve and nullif(trim(p_note), '') is null then
    perform private.raise_error(422, 'reason_required', 'Give a reason for rejecting');
  end if;

  v_state := coalesce(private.clean_location_name(p_state), r.state_name);
  v_district := case when r.kind in ('district', 'city') then coalesce(private.clean_location_name(p_district), r.district_name) end;
  v_city := case when r.kind = 'city' then coalesce(private.clean_location_name(p_city), r.city_name) end;

  if p_approve then
    perform private.ensure_location(v_state, v_district, v_city);
  end if;

  update public.location_requests
     set status = case when p_approve then 'approved'::public.location_request_status else 'rejected' end,
         state_name = v_state, district_name = v_district, city_name = v_city,
         decided_by = (select auth.uid()), decided_at = now(), decision_note = nullif(trim(p_note), '')
   where id = r.id;

  perform private.write_audit('location_request.' || case when p_approve then 'approve' else 'reject' end,
    'location_requests', r.id::text, to_jsonb(r),
    jsonb_build_object('state', v_state, 'district', v_district, 'city', v_city), p_note);

  if r.requested_by is not null then
    perform private.notify(r.requested_by, 'system',
      case when p_approve then 'location.approved' else 'location.rejected' end,
      case when p_approve then 'Location added' else 'Location not added' end,
      case when p_approve
        then '"' || concat_ws(', ', v_city, v_district, v_state) || '" is now in the list.'
        else '"' || concat_ws(', ', v_city, v_district, v_state) || '" was not added: ' || trim(p_note) end,
      jsonb_build_object('location_request_id', r.id));
  end if;
end;
$$;

-- Business registration with a district on the registered address.
drop function if exists public.create_business(text, text, text, text, text, public.business_type, text, text, text, text, text, text, text);

create or replace function public.create_business(
  p_legal_name text,
  p_display_name text,
  p_owner_full_name text,
  p_contact_phone text,
  p_contact_email text,
  p_business_type public.business_type,
  p_registration_number text default null,
  p_gstin text default null,
  p_registered_address_line1 text default null,
  p_registered_address_line2 text default null,
  p_registered_city text default null,
  p_registered_state text default null,
  p_registered_postal_code text default null,
  p_registered_district text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_id uuid;
begin
  if v_user is null then
    perform private.raise_error(401, 'not_authenticated');
  end if;
  if private.is_platform_staff() then
    perform private.raise_error(403, 'staff_cannot_own_business', 'Platform staff accounts cannot register businesses');
  end if;
  if (select count(*) from public.businesses where owner_id = v_user and archived_at is null) >= 10 then
    perform private.raise_error(422, 'business_limit_reached');
  end if;
  insert into public.businesses (owner_id, legal_name, display_name, owner_full_name, contact_phone, contact_email,
                                 business_type, registration_number, gstin, registered_address_line1,
                                 registered_address_line2, registered_city, registered_district, registered_state,
                                 registered_postal_code)
  values (v_user, trim(p_legal_name), nullif(trim(p_display_name), ''), trim(p_owner_full_name), p_contact_phone,
          lower(trim(p_contact_email)), p_business_type, nullif(trim(p_registration_number), ''),
          nullif(upper(trim(p_gstin)), ''), p_registered_address_line1, p_registered_address_line2,
          p_registered_city, p_registered_district, p_registered_state, p_registered_postal_code)
  returning id into v_id;
  insert into public.business_members (business_id, user_id, role, added_by) values (v_id, v_user, 'owner', v_user);
  perform private.write_audit('business.create', 'businesses', v_id::text, null,
                              jsonb_build_object('legal_name', p_legal_name, 'business_type', p_business_type));
  return v_id;
end;
$$;

-------------------------------------------------------------------------------
-- Privileges
-------------------------------------------------------------------------------

revoke all on public.location_states, public.location_districts, public.location_cities, public.location_requests
  from anon, authenticated;
grant select on public.location_states, public.location_districts, public.location_cities to anon, authenticated;
grant select on public.location_requests to authenticated;
grant all on public.location_states, public.location_districts, public.location_cities, public.location_requests
  to service_role;
grant update (registered_district) on public.businesses to authenticated;

revoke execute on function
  private.clean_location_name(text),
  private.ensure_location(text, text, text),
  public.request_location(public.location_kind, text, text, text, text),
  public.decide_location_request(uuid, boolean, text, text, text, text),
  public.create_business(text, text, text, text, text, public.business_type, text, text, text, text, text, text, text, text)
  from public, anon;
grant execute on function
  private.clean_location_name(text),
  private.ensure_location(text, text, text),
  public.request_location(public.location_kind, text, text, text, text),
  public.decide_location_request(uuid, boolean, text, text, text, text),
  public.create_business(text, text, text, text, text, public.business_type, text, text, text, text, text, text, text, text)
  to authenticated, service_role;
revoke execute on function private.ensure_location(text, text, text) from authenticated;

