join public.location_states s on s.code = v.code
join public.location_districts d on d.state_id = s.id and d.name = v.district
on conflict do nothing;

-- Keep values already used by stations selectable (only under known states).
insert into public.location_districts (state_id, name)
select distinct on (s.id, lower(trim(st.district))) s.id, trim(st.district)
  from public.stations st join public.location_states s on lower(s.name) = lower(trim(st.state))
on conflict do nothing;

insert into public.location_cities (district_id, name)
select distinct on (d.id, lower(trim(st.city))) d.id, trim(st.city)
  from public.stations st
  join public.location_states s on lower(s.name) = lower(trim(st.state))
  join public.location_districts d on d.state_id = s.id and lower(d.name) = lower(trim(st.district))
on conflict do nothing;
